      if (info.type === "cancel") {
        rmSync(full, { force: true });
        const p = pending.get(info.id);
        if (p) {
          const r = cancelAsk(p.ask, Date.now());
          if (r) settle(p, r);
        }
        continue;
      }
      let raw = "";
      try {
        raw = readFileSync(full, "utf8");
        rmSync(full, { force: true });
      } catch {
        continue;
      }
      if (info.kind === "notify") {
        // 需求 1：通知输入 → 下一轮用户消息（空输入忽略）；
