          spawnSync("termux-toast", ["已收到回复 ✓"], { encoding: "utf8" });
          pi.sendUserMessage(reply.text);
        }
        continue;
      }
      const p = pending.get(info.id);
      if (!p) continue;
      const reply = decodeReply(raw);
      let r: AskResult | null;
      if (reply === null) {
        // 空输入 = 取消（SPEC §4.1）
        r = cancelAsk(p.ask, Date.now());
